export default function input({ body, headers, expected, calendarId }) {
  if (!expected || headers.authorization !== expected) throw Error("Unauthorized");
  if (!calendarId || calendarId.includes("YOUR_")) throw Error("Configure calendar");
  const x = body,
    op = String(x.operation || "");
  if (!["SearchEvent", "CreateEvent", "UpdateEvent", "DeleteEvent"].includes(op))
    throw Error("Unknown operation");
  const id = String(x.eventId || ""),
    requestId = String(x.requestId || "");
  if (op !== "SearchEvent" && !/^[A-Za-z0-9_-]{1,100}$/.test(requestId))
    throw Error("Unique requestId required");
  if (["UpdateEvent", "DeleteEvent"].includes(op) && !id) throw Error("Event ID required");
  const start = String(x.start || ""),
    end = String(x.end || "");
  if (
    ["CreateEvent", "UpdateEvent"].includes(op) &&
    (!Number.isFinite(Date.parse(start)) ||
      !Number.isFinite(Date.parse(end)) ||
      Date.parse(end) <= Date.parse(start))
  )
    throw Error("Valid start/end required");
  const limit = Number(x.limit || 10);
  if (op === "SearchEvent" && (!Number.isInteger(limit) || limit < 1 || limit > 250))
    throw Error("Limit must be 1–250");
  return {
    operation: op,
    calendarId,
    eventId: id || "not-applicable",
    requestId,
    fingerprint: JSON.stringify({ op, id, start, end, title: x.title, description: x.description }),
    key: "calendar-mcp:" + op + ":" + requestId,
    timeMin: x.after ? String(x.after) : null,
    timeMax: x.before ? String(x.before) : null,
    limit,
    event: {
      summary: String(x.title || ""),
      description: String(x.description || ""),
      start: { dateTime: start },
      end: { dateTime: end },
    },
  };
}

