export default async function reserve({ key, fingerprint, acknowledge, resolution }, ctx) {
  let s = await ctx.state.get(key);
  if (s && s.fingerprint !== fingerprint) throw Error("Request ID reused with different input");
  if (s?.status === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending " + key);
    if (resolution === "confirmed") {
      await ctx.state.set(key, { status: "done", fingerprint });
      return { write: false };
    }
    await ctx.state.set(key, null);
    s = null;
  }
  if (s?.status === "done") return { write: false };
  await ctx.state.set(key, { status: "pending", fingerprint });
  return { write: true };
}

